{"hypotheses":[
  {"statement":"Beverage revenue is high primarily because a small number of products dominate drink sales (concentration effect), not broad-based demand.","priorConfidence":0.55,"target":"beverage_revenue_by_product","action":"breakdown","expectation":"Top 1-2 products in product_name account for a disproportionate share (e.g. >50%) of order_item.drink_revenue; if revenue is evenly spread across many products, this is refuted."},
  {"statement":"Beverage revenue is high because one customer_type segment (e.g. a specific business/loyalty tier) drives disproportionate beverage spend, not uniform demand across customer types.","priorConfidence":0.5,"target":"top_beverage_customers","action":"breakdown","expectation":"drink_revenue or lifetime_spend_pretax concentrated heavily in one customer_type when broken down; if spend is roughly even across customer_type, this is refuted."},
  {"statement":"High beverage revenue reflects a recent upward trend (recent growth spike) rather than a stable historical pattern.","priorConfidence":0.4,"target":"order_item.revenue_growth_mom","action":"compare_time","expectation":"order_item.revenue_growth_mom for drink-related revenue shows a sharp positive trend in recent months; if growth is flat or negative, this is refuted."},
  {"statement":"Beverage revenue is high due to higher order volume (more drink_orders) rather than higher revenue per drink order.","priorConfidence":0.45,"target":"orders.drink_orders","action":"compare_time","expectation":"orders.drink_orders count is elevated/growing in proportion to order_item.drink_revenue growth; if drink_revenue grows while drink_orders stays flat, this is refuted in favor of price/mix effects."},
  {"statement":"Beverage revenue's high share is explained by drinks being priced/valued higher per item than food, not by higher volume.","priorConfidence":0.35,"target":"order_item.drink_revenue_pct","action":"lookup_metric","expectation":"order_item.drink_revenue_pct exceeds order volume share of drink_orders relative to food_orders, indicating higher per-unit revenue for drinks; if the percentage share matches order-count share, this is refuted."}
]}
